package reviewstore

import (
	"encoding/json"
	"os"
	"testing"
)

// TestAnchorConformance requires every anchor the editor authors to resolve
// here (#404).
//
// testdata/anchor_conformance.json is generated by the frontend test
// frontend/src/utils/anchorConformance.test.ts, which parses each case with
// the editor's own extensions and records the anchor the editor would create
// for every block. A comment created in the editor is orphaned the moment the
// backend cannot resolve its anchor, so any failure here is exactly that bug.
//
// Lines are also required to come out in document order, which catches an
// anchor that resolves but to the wrong line.
func TestAnchorConformance(t *testing.T) {
	raw, err := os.ReadFile("testdata/anchor_conformance.json")
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}
	var cases []struct {
		Name     string `json:"name"`
		Markdown string `json:"markdown"`
		Anchors  []struct {
			Snippet     string   `json:"snippet"`
			HeadingPath []string `json:"heading_path"`
			Occurrence  int      `json:"occurrence"`
		} `json:"anchors"`
	}
	if err := json.Unmarshal(raw, &cases); err != nil {
		t.Fatalf("parse fixture: %v", err)
	}
	if len(cases) == 0 {
		t.Fatal("fixture has no cases")
	}
	for _, c := range cases {
		t.Run(c.Name, func(t *testing.T) {
			if len(c.Anchors) == 0 {
				t.Fatal("case has no anchors")
			}
			prev := 0
			for _, fa := range c.Anchors {
				a := Anchor{HeadingPath: fa.HeadingPath, Snippet: fa.Snippet, Occurrence: fa.Occurrence}
				lr, ok := ResolveAnchor(c.Markdown, a)
				if !ok {
					t.Errorf("orphan: heading_path=%q snippet=%q occurrence=%d", fa.HeadingPath, fa.Snippet, fa.Occurrence)
					continue
				}
				if lr[0] < prev {
					t.Errorf("snippet %q resolved to line %d, before the previous anchor's line %d", fa.Snippet, lr[0], prev)
				}
				prev = lr[0]
			}
		})
	}
}
